--- /dev/null
+++ b/js/theme.js
@@ -0,0 +1,40 @@
+// Initial theme script. Loaded with blocking="render" so the stored theme is
+// applied before first paint and before a cross-document view transition
+// captures the new page.
+(() => {
+  const root = document.documentElement;
+  const KEY = 'theme';
+
+  let stored = null;
+  try {
+    stored = localStorage.getItem(KEY);
+  } catch {
+    // Storage may be unavailable (privacy mode); fall back to system pref.
+  }
+
+  const prefersDark = matchMedia('(prefers-color-scheme: dark)').matches;
+  root.dataset.theme = stored === 'dark' || stored === 'light'
+    ? stored
+    : (prefersDark ? 'dark' : 'light');
+
+  const sync = () => {
+    for (const btn of document.querySelectorAll('[data-theme-toggle]')) {
+      btn.setAttribute('aria-pressed', String(root.dataset.theme === 'dark'));
+    }
+  };
+
+  document.addEventListener('click', (event) => {
+    if (!event.target.closest('[data-theme-toggle]')) return;
+    root.dataset.theme = root.dataset.theme === 'dark' ? 'light' : 'dark';
+    try {
+      localStorage.setItem(KEY, root.dataset.theme);
+    } catch {}
+    sync();
+  });
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', sync, { once: true });
+  } else {
+    sync();
+  }
+})();
