+// Resolve the accumulated samples (as smallpt does: clamp each sub-pixel mean,
+// average the 2x2, gamma-correct) into RGBA and return a pointer to it.
+EMSCRIPTEN_KEEPALIVE uint8_t* sp_get_rgba(int passes) {
+  size_t px = size_t(W) * size_t(row1 - row0);
+  double inv = 1.0 / passes;
+  for (size_t i = 0; i < px; i++) {
