@@ -0,0 +1,27 @@
+// Web Worker that runs the smallpt WebAssembly module off the main thread.
+// Message in:  { w, h, spp, colors: [[index, r, g, b], ...], rows: [y, ...] }
+// Messages out: { type: 'row', y, data: Uint8ClampedArray(w*4) } per row,
+//               then { type: 'done' }.  (y = 0 is the top canvas row.)
+importScripts('smallpt.js');
+
+const ready = createSmallpt();
+
+self.onmessage = async ({ data: job }) => {
+  try {
+    const M = await ready;
+    M._reset_scene();
+    for (const [i, r, g, b] of job.colors) M._set_sphere_color(i, r, g, b);
+    const ptr = M._init(job.w, job.h, job.spp);
+    const rowBytes = job.w * 4;
+    for (const canvasY of job.rows) {
+      // smallpt's y runs bottom-up; the framebuffer is stored top-down.
+      M._render_row(job.h - 1 - canvasY);
+      const start = ptr + canvasY * rowBytes;
+      const row = new Uint8ClampedArray(M.HEAPU8.slice(start, start + rowBytes).buffer);
+      self.postMessage({ type: 'row', y: canvasY, data: row }, [row.buffer]);
+    }
+    self.postMessage({ type: 'done' });
+  } catch (err) {
+    self.postMessage({ type: 'error', message: String(err && err.message || err) });
+  }
+};
