+    let sum = 0;
+    for (const it of doc.items) {
+      expectPlainObject(it, 'Item');
+      expectExactKeys(it, ['name', 'unitPriceCents', 'quantity'], 'Item');
+      expectText(it.name, 'item name', 80);
+      expectInt(it.unitPriceCents, 'unit price', 0, 1_000_00);
+      expectInt(it.quantity, 'quantity', 1, 99);
+      sum += it.unitPriceCents * it.quantity;
+    }
+    expectInt(doc.subtotalCents, 'subtotal', 0, MAX_CENTS);
+    expectInt(doc.taxCents, 'tax', 0, MAX_CENTS);
+    expectInt(doc.totalCents, 'total', 0, MAX_CENTS);
+    if (sum !== doc.subtotalCents) throw new Error('Subtotal does not match line items');
+    if (doc.subtotalCents + doc.taxCents !== doc.totalCents) throw new Error('Total does not equal subtotal + tax');
+  } else if (doc.type === 'voucher') {
+    expectExactKeys(doc, ['type', 'voucherCode', 'issuedAt', 'recipient', 'from', 'amountCents', 'currency', 'expiresOn', 'message'], 'Voucher');
+    if (typeof doc.voucherCode !== 'string' || !/^DG-V-[A-Z0-9]{4}(-[A-Z0-9]{4}){3}$/.test(doc.voucherCode)) throw new Error('Invalid voucher code');
+    expectTimestamp(doc.issuedAt, 'issue time');
+    expectText(doc.recipient, 'recipient', 80);
+    expectText(doc.from, 'sender', 80);
+    expectInt(doc.amountCents, 'voucher amount', 100, 500_00);
+    if (doc.currency !== 'USD') throw new Error('Unsupported currency');
+    expectDate(doc.expiresOn, 'expiry date');
+    if (doc.expiresOn < doc.issuedAt.slice(0, 10)) throw new Error('Voucher expires before it was issued');
+    expectText(doc.message, 'message', 200, { allowEmpty: true });
+  } else {
+    throw new Error('Unknown document type');
+  }
+  return doc;
+}
+
+function signingInput(envelopeWithoutSignatures) {
+  return concatBytes(utf8(DOMAIN_TAG), utf8(canonicalize(envelopeWithoutSignatures)));
+}
+
+/** Signs a receipt or voucher, returning a self-contained signed envelope. */
+export async function signDocument(doc, key) {
+  validateDocument(doc);
+  const suite = SUITES[key.suite];
+  if (!suite) throw new Error('Unknown key suite');
+  const unsigned = {
+    format: FORMAT,
+    document: doc,
+    signer: { suite: key.suite, keyId: key.keyId, label: key.label, publicKeys: [...key.publicKeys] },
+    signedAt: new Date().toISOString(),
+  };
+  const msg = signingInput(unsigned);
+  const signatures = [];
+  for (let i = 0; i < suite.algs.length; i++) {
+    signatures.push(b64urlEncode(await ALGS[suite.algs[i]].sign(key.privateKeys[i], msg)));
+  }
+  return { ...unsigned, signatures };
+}
+
+function parseJsonLimited(text) {
+  if (typeof text !== 'string') throw new Error('Expected JSON text');
+  if (utf8(text).length > MAX_INPUT_BYTES) throw new Error('Input is too large');
+  try {
+    return JSON.parse(text);
+  } catch {
+    throw new Error('Input is not valid JSON');
+  }
+}
+
+/**
+ * Verifies a signed envelope.
+ *
+ * @param {string|object} input  Envelope JSON text or parsed object.
+ * @param {object} opts
+ * @param {Iterable<string>} opts.trustedKeyIds  Key IDs the verifier trusts.
+ * @param {Date} [opts.now]
+ * @returns {Promise<{status: 'authentic'|'untrusted'|'invalid', checks: {label:string, ok:boolean|null, detail?:string}[], envelope?:object, error?:string, expired?:boolean}>}
+ *   - authentic:  every signature is valid and the key is trusted
+ *   - untrusted:  every signature is valid but the key isn't trusted, so the
+ *                 contents are intact but the issuer is unproven
+ *   - invalid:    malformed, tampered, or signature mismatch
+ */
+export async function verifyDocument(input, { trustedKeyIds = [], now = new Date() } = {}) {
+  const checks = [];
+  const fail = (label, err) => {
+    checks.push({ label, ok: false, detail: err?.message || String(err) });
+    return { status: 'invalid', checks, error: checks.at(-1).detail };
+  };
+
+  let env;
+  try {
+    env = typeof input === 'string' ? parseJsonLimited(input) : input;
+    expectPlainObject(env, 'Signed document');
+    expectExactKeys(env, ['format', 'document', 'signer', 'signedAt', 'signatures'], 'Signed document');
+    if (env.format !== FORMAT) throw new Error('Unsupported format');
+    expectTimestamp(env.signedAt, 'signing time');
+  } catch (e) {
+    return fail('Well-formed signed document', e);
+  }
+  checks.push({ label: 'Well-formed signed document', ok: true });
+
+  let suite, publicKeys, signatures;
+  try {
+    expectPlainObject(env.signer, 'Signer');
+    expectExactKeys(env.signer, ['suite', 'keyId', 'label', 'publicKeys'], 'Signer');
+    if (typeof env.signer.label !== 'string' || env.signer.label.length > 60) throw new Error('Invalid signer label');
+    publicKeys = checkPublicKeys(env.signer.suite, env.signer.publicKeys);
+    suite = SUITES[env.signer.suite];
+    if (!Array.isArray(env.signatures) || env.signatures.length !== suite.algs.length) throw new Error('Wrong number of signatures');
+    signatures = env.signatures.map((s, i) => {
+      const bytes = b64urlDecode(s);
+      if (bytes.length !== ALGS[suite.algs[i]].signatureBytes) throw new Error(`Bad ${suite.algs[i]} signature length`);
+      return bytes;
+    });
+    if (await computeKeyId(env.signer.suite, env.signer.publicKeys) !== env.signer.keyId) throw new Error('Key ID does not match public key');
+  } catch (e) {
+    return fail('Signer key and signature encoding', e);
+  }
+  checks.push({ label: `Signer key and signature encoding (${suite.label})`, ok: true });
+
+  try {
+    validateDocument(env.document);
+  } catch (e) {
+    return fail('Document contents', e);
+  }
+  checks.push({ label: 'Document contents and totals', ok: true });
+
+  const { signatures: _omit, ...unsigned } = env;
+  const msg = signingInput(unsigned);
+  for (let i = 0; i < suite.algs.length; i++) {
+    const alg = suite.algs[i];
+    let ok = false;
+    try {
+      ok = await ALGS[alg].verify(publicKeys[i], signatures[i], msg);
+    } catch (e) {
+      return fail(`${alg} signature`, new Error(`Cannot verify ${alg} in this browser: ${e.message}`));
+    }
+    if (!ok) return fail(`${alg} signature`, new Error('Signature does not match — the document was altered or signed with a different key'));
+    checks.push({ label: `${alg} signature`, ok: true });
+  }
+
+  const trusted = new Set(trustedKeyIds).has(env.signer.keyId);
+  checks.push({
+    label: 'Signer is a trusted Daily Grind key',
+    ok: trusted ? true : null,
+    detail: trusted ? undefined : `Key ${formatFingerprint(env.signer.keyId)} is not in your trusted keys`,
+  });
+
+  let expired = false;
+  if (env.document.type === 'voucher') {
+    expired = env.document.expiresOn < now.toISOString().slice(0, 10);
+    checks.push({ label: 'Voucher not expired', ok: expired ? false : true, detail: expired ? `Expired on ${env.document.expiresOn}` : undefined });
+  }
+
+  return { status: trusted ? 'authentic' : 'untrusted', checks, envelope: env, expired };
+}
diff --git a/js/dg-signing-ui.js b/js/dg-signing-ui.js
new file mode 100644
index 0000000..4e502bf
--- /dev/null
+++ b/js/dg-signing-ui.js
@@ -0,0 +1,489 @@
+/**
+ * UI for signing and verifying Daily Grind receipts and gift vouchers.
+ *
+ * Storage:
+ *   - Signing keys: IndexedDB. WebCrypto private keys are stored as
+ *     non-extractable CryptoKeys. ML-DSA secret keys are stored as raw bytes
+ *     because browsers don't support ML-DSA natively yet.
+ *   - Trusted public keys: localStorage (public data only).
+ *
+ * All user-controlled text is rendered with textContent, never innerHTML.
+ */
+import {
+  SUITES, isSuiteSupported, generateSigningKey, exportPublicKey, parsePublicKey,
+  formatFingerprint, buildReceipt, buildVoucher, signDocument, verifyDocument, MAX_INPUT_BYTES,
+} from './dg-crypto.js';
+
+const MENU = [
+  { name: 'Maple Oat Latte', unitPriceCents: 575 },
+  { name: 'Dark Roast Espresso', unitPriceCents: 350 },
+  { name: 'Cold Brew', unitPriceCents: 495 },
+  { name: 'Cappuccino', unitPriceCents: 450 },
+  { name: 'Butter Croissant', unitPriceCents: 375 },
+];
+const TAX_RATE_BPS = 825;
+const TRUSTED_KEY_STORE = 'dg-trusted-keys';
+const ACTIVE_KEY_STORE = 'dg-active-key';
+
+const $ = (id) => document.getElementById(id);
+const money = (cents) => `$${(cents / 100).toFixed(2)}`;
+
+function el(tag, props = {}, ...children) {
+  const node = document.createElement(tag);
+  for (const [k, v] of Object.entries(props)) {
+    if (k === 'class') node.className = v;
+    else if (k === 'text') node.textContent = v;
+    else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
+    else node.setAttribute(k, v);
+  }
+  for (const c of children) if (c != null) node.append(c);
+  return node;
+}
+
+function setStatus(target, message, kind = 'info') {
+  target.textContent = message;
+  target.dataset.kind = kind;
+}
+
+/* ------------------------------------------------------------------ */
+/* Key storage                                                         */
+/* ------------------------------------------------------------------ */
+
+const keyDb = {
+  _db: null,
+  open() {
+    this._db ??= new Promise((resolve, reject) => {
+      const req = indexedDB.open('daily-grind-signing', 1);
+      req.onupgradeneeded = () => req.result.createObjectStore('keys', { keyPath: 'keyId' });
+      req.onsuccess = () => resolve(req.result);
+      req.onerror = () => reject(req.error);
+    });
+    return this._db;
+  },
+  async tx(mode, fn) {
+    const db = await this.open();
+    return new Promise((resolve, reject) => {
+      const t = db.transaction('keys', mode);
+      const req = fn(t.objectStore('keys'));
+      t.oncomplete = () => resolve(req?.result);
+      t.onerror = () => reject(t.error);
+      t.onabort = () => reject(t.error);
+    });
+  },
+  all() { return this.tx('readonly', (s) => s.getAll()); },
+  put(key) { return this.tx('readwrite', (s) => s.put(key)); },
+  remove(keyId) { return this.tx('readwrite', (s) => s.delete(keyId)); },
+};
+
+function loadTrusted() {
+  try {
+    const list = JSON.parse(localStorage.getItem(TRUSTED_KEY_STORE) || '[]');
+    return Array.isArray(list) ? list : [];
+  } catch {
+    return [];
+  }
+}
+function saveTrusted(list) {
+  localStorage.setItem(TRUSTED_KEY_STORE, JSON.stringify(list));
+}
+
+/* ------------------------------------------------------------------ */
+/* State                                                               */
+/* ------------------------------------------------------------------ */
+
+const state = {
+  keys: [],
+  trusted: [],
+  activeKeyId: localStorage.getItem(ACTIVE_KEY_STORE),
+  lastSigned: null,
+};
+
+async function trustedKeyIds() {
+  // Your own keys count as trusted. Re-validate pinned bundles in case
+  // localStorage was edited.
+  const ids = new Set(state.keys.map((k) => k.keyId));
+  for (const t of state.trusted) {
+    try { ids.add((await parsePublicKey(t)).keyId); } catch { /* ignore corrupt entry */ }
+  }
+  return ids;
+}
+
+/* ------------------------------------------------------------------ */
+/* Key management UI                                                   */
+/* ------------------------------------------------------------------ */
+
+async function initSuiteSelect() {
+  const select = $('dg-suite');
+  select.replaceChildren();
+  for (const [id, suite] of Object.entries(SUITES)) {
+    const supported = await isSuiteSupported(id);
+    const opt = el('option', { value: id, text: suite.label + (supported ? '' : ' — not supported in this browser') });
+    if (!supported) opt.disabled = true;
+    select.append(opt);
+  }
+  const preferred = ['hybrid-ed25519-ml-dsa-65', 'ml-dsa-65', 'ecdsa-p256'].find((id) => !select.querySelector(`option[value="${id}"]`).disabled);
+  if (preferred) select.value = preferred;
+}
+
+function renderKeys() {
+  const list = $('dg-key-list');
+  list.replaceChildren();
+  if (state.keys.length === 0) {
+    list.append(el('li', { class: 'dg-empty', text: 'No signing keys yet. Generate one to start issuing signed documents.' }));
+  }
+  if (!state.keys.some((k) => k.keyId === state.activeKeyId)) {
+    state.activeKeyId = state.keys[0]?.keyId ?? null;
+  }
+  for (const key of state.keys) {
+    const suite = SUITES[key.suite];
+    const radio = el('input', { type: 'radio', name: 'dg-active-key', value: key.keyId, 'aria-label': `Use ${key.label} for signing` });
+    radio.checked = key.keyId === state.activeKeyId;
+    radio.addEventListener('change', () => {
+      state.activeKeyId = key.keyId;
+      localStorage.setItem(ACTIVE_KEY_STORE, key.keyId);
+      updateSignButton();
+    });
+    list.append(el('li', { class: 'dg-key' },
+      el('label', { class: 'dg-key-main' },
+        radio,
+        el('span', {},
+          el('strong', { text: key.label }),
+          suite.quantumResistant ? el('span', { class: 'dg-badge dg-badge-pq', text: 'Quantum-resistant' }) : el('span', { class: 'dg-badge', text: 'Classical' }),
+          el('br'),
+          el('small', { text: `${suite.label} · ${formatFingerprint(key.keyId)}` }),
+        ),
+      ),
+      el('span', { class: 'dg-key-actions' },
+        el('button', { type: 'button', class: 'dg-link', text: 'Export public key', onclick: () => exportKey(key) }),
+        el('button', { type: 'button', class: 'dg-link dg-danger', text: 'Delete', onclick: () => deleteKey(key) }),
+      ),
+    ));
+  }
+  if (state.activeKeyId) localStorage.setItem(ACTIVE_KEY_STORE, state.activeKeyId);
+  updateSignButton();
+}
+
+function renderTrusted() {
+  const list = $('dg-trusted-list');
+  list.replaceChildren();
+  if (state.trusted.length === 0) {
+    list.append(el('li', { class: 'dg-empty', text: 'No other trusted keys. Your own keys are always trusted.' }));
+  }
+  state.trusted.forEach((t, i) => {
+    list.append(el('li', { class: 'dg-key' },
+      el('span', {},
+        el('strong', { text: String(t.label) }),
+        el('br'),
+        el('small', { text: `${SUITES[t.suite]?.label ?? 'Unknown suite'} · ${safeFingerprint(t.keyId)}` }),
+      ),
+      el('button', {
+        type: 'button', class: 'dg-link dg-danger', text: 'Remove', onclick: () => {
+          state.trusted.splice(i, 1);
+          saveTrusted(state.trusted);
+          renderTrusted();
+        },
+      }),
+    ));
+  });
+}
+
+function safeFingerprint(keyId) {
+  try { return formatFingerprint(keyId); } catch { return 'invalid key ID'; }
+}
+
+async function generateKey() {
+  const status = $('dg-key-status');
+  const btn = $('dg-generate');
+  btn.disabled = true;
+  setStatus(status, 'Generating key…');
+  try {
+    const key = await generateSigningKey($('dg-suite').value, $('dg-key-label').value);
+    await keyDb.put(key);
+    state.keys.push(key);
+    state.activeKeyId = key.keyId;
+    renderKeys();
+    setStatus(status, `Created key ${formatFingerprint(key.keyId)}. It's stored only in this browser.`, 'ok');
+  } catch (e) {
+    setStatus(status, `Could not generate key: ${e.message}`, 'error');
+  } finally {
+    btn.disabled = false;
+  }
+}
+
+function exportKey(key) {
+  const json = JSON.stringify(exportPublicKey(key), null, 2);
+  download(`daily-grind-public-key-${formatFingerprint(key.keyId)}.json`, json);
+  setStatus($('dg-key-status'), 'Public key downloaded. Share it with anyone who needs to verify your documents.', 'ok');
+}
+
+async function deleteKey(key) {
+  if (!confirm(`Delete signing key "${key.label}"? Documents already signed with it can still be verified only if someone keeps its public key.`)) return;
+  await keyDb.remove(key.keyId);
+  state.keys = state.keys.filter((k) => k.keyId !== key.keyId);
+  renderKeys();
+  setStatus($('dg-key-status'), 'Key deleted.', 'info');
+}
+
+async function addTrustedKey(text) {
+  const status = $('dg-trust-status');
+  try {
+    const pub = await parsePublicKey(text);
+    if (!state.trusted.some((t) => t.keyId === pub.keyId) && !state.keys.some((k) => k.keyId === pub.keyId)) {
+      state.trusted.push({ format: 'daily-grind-public-key/v1', ...pub });
+      saveTrusted(state.trusted);
+    }
+    renderTrusted();
+    setStatus(status, `Trusted key ${formatFingerprint(pub.keyId)} (${pub.label}).`, 'ok');
+    return true;
+  } catch (e) {
+    setStatus(status, `Could not add key: ${e.message}`, 'error');
+    return false;
+  }
+}
+
+/* ------------------------------------------------------------------ */
+/* Issuing                                                             */
+/* ------------------------------------------------------------------ */
+
+function initIssueForms() {
+  const items = $('dg-receipt-items');
+  MENU.forEach((m, i) => {
+    items.append(el('label', { class: 'dg-item' },
+      el('span', { text: `${m.name} (${money(m.unitPriceCents)})` }),
+      el('input', { type: 'number', min: '0', max: '99', step: '1', value: i === 0 ? '1' : '0', 'data-index': String(i), 'aria-label': `Quantity of ${m.name}` }),
+    ));
+  });
+  items.addEventListener('input', updateReceiptTotal);
+  updateReceiptTotal();
+
+  const expiry = new Date();
+  expiry.setUTCFullYear(expiry.getUTCFullYear() + 1);
+  $('dg-voucher-expiry').value = expiry.toISOString().slice(0, 10);
+  $('dg-voucher-expiry').min = new Date().toISOString().slice(0, 10);
+
+  for (const tab of document.querySelectorAll('[data-dg-tab]')) {
+    tab.addEventListener('click', () => selectTab(tab.dataset.dgTab));
+  }
+  $('dg-issue-form').addEventListener('submit', (e) => { e.preventDefault(); issue(); });
+  $('dg-copy').addEventListener('click', copySigned);
+  $('dg-download').addEventListener('click', () => {
+    if (state.lastSigned) download(`${state.lastSigned.id}.signed.json`, state.lastSigned.json);
+  });
+  $('dg-send-to-verify').addEventListener('click', () => {
+    if (!state.lastSigned) return;
+    $('dg-verify-input').value = state.lastSigned.json;
+    $('dg-verify-input').scrollIntoView({ behavior: 'smooth', block: 'center' });
+    verify();
+  });
+}
+
+function selectTab(name) {
+  for (const tab of document.querySelectorAll('[data-dg-tab]')) {
+    const active = tab.dataset.dgTab === name;
+    tab.setAttribute('aria-selected', String(active));
+    $(tab.getAttribute('aria-controls')).hidden = !active;
+  }
+}
+
+function receiptItems() {
+  return [...$('dg-receipt-items').querySelectorAll('input')].map((input) => {
+    const qty = Math.trunc(Number(input.value));
+    return { ...MENU[Number(input.dataset.index)], quantity: Number.isFinite(qty) ? Math.min(Math.max(qty, 0), 99) : 0 };
+  });
+}
+
+function updateReceiptTotal() {
+  const subtotal = receiptItems().reduce((n, it) => n + it.unitPriceCents * it.quantity, 0);
+  const tax = Math.round((subtotal * TAX_RATE_BPS) / 10_000);
+  $('dg-receipt-total').textContent = `Subtotal ${money(subtotal)} · Tax ${money(tax)} · Total ${money(subtotal + tax)}`;
+}
+
+function updateSignButton() {
+  const btn = $('dg-sign');
+  btn.disabled = !state.activeKeyId;
+  btn.title = state.activeKeyId ? '' : 'Generate a signing key first';
+}
+
+async function issue() {
+  const status = $('dg-issue-status');
+  const key = state.keys.find((k) => k.keyId === state.activeKeyId);
+  if (!key) return setStatus(status, 'Generate or select a signing key first.', 'error');
+  const isReceipt = $('dg-tab-receipt').getAttribute('aria-selected') === 'true';
+  try {
+    const doc = isReceipt
+      ? buildReceipt({ customer: $('dg-receipt-customer').value, store: $('dg-receipt-store').value, items: receiptItems(), taxRateBps: TAX_RATE_BPS })
+      : buildVoucher({
+        recipient: $('dg-voucher-recipient').value,
+        from: $('dg-voucher-from').value,
+        amountCents: Math.round(Number($('dg-voucher-amount').value) * 100),
+        expiresOn: $('dg-voucher-expiry').value,
+        message: $('dg-voucher-message').value,
+      });
+    setStatus(status, 'Signing…');
+    const envelope = await signDocument(doc, key);
+    const json = JSON.stringify(envelope, null, 2);
+    state.lastSigned = { id: doc.receiptId || doc.voucherCode, json };
+    $('dg-signed-output').value = json;
+    $('dg-signed-block').hidden = false;
+    setStatus(status, `Signed ${isReceipt ? 'receipt' : 'voucher'} ${state.lastSigned.id} with ${SUITES[key.suite].label}.`, 'ok');
+  } catch (e) {
+    setStatus(status, `Could not sign: ${e.message}`, 'error');
+  }
+}
+
+async function copySigned() {
+  if (!state.lastSigned) return;
+  try {
+    await navigator.clipboard.writeText(state.lastSigned.json);
+    setStatus($('dg-issue-status'), 'Signed document copied to clipboard.', 'ok');
+  } catch {
+    $('dg-signed-output').select();
+    setStatus($('dg-issue-status'), 'Clipboard unavailable. The text is selected so you can copy it manually.', 'info');
+  }
+}
+
+function download(filename, text) {
+  const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
+  const a = el('a', { href: url, download: filename.replace(/[^A-Za-z0-9._-]/g, '_') });
+  document.body.append(a);
+  a.click();
+  a.remove();
+  setTimeout(() => URL.revokeObjectURL(url), 1000);
+}
+
+/* ------------------------------------------------------------------ */
+/* Verification                                                        */
+/* ------------------------------------------------------------------ */
+
+function initVerify() {
+  $('dg-verify-form').addEventListener('submit', (e) => { e.preventDefault(); verify(); });
+  $('dg-verify-file').addEventListener('change', async (e) => {
+    const file = e.target.files?.[0];
+    if (!file) return;
+    if (file.size > MAX_INPUT_BYTES) {
+      renderVerifyError('File is too large to be a Daily Grind signed document.');
+      return;
+    }
+    $('dg-verify-input').value = await file.text();
+    e.target.value = '';
+    verify();
+  });
+}
+
+function renderVerifyError(message) {
+  const out = $('dg-verify-result');
+  out.hidden = false;
+  out.dataset.status = 'invalid';
+  out.replaceChildren(el('p', { class: 'dg-verdict', text: `✗ ${message}` }));
+}
+
+async function verify() {
+  const out = $('dg-verify-result');
+  const text = $('dg-verify-input').value.trim();
+  if (!text) return renderVerifyError('Paste or upload a signed receipt or voucher first.');
+
+  const result = await verifyDocument(text, { trustedKeyIds: await trustedKeyIds() });
+  out.hidden = false;
+  out.dataset.status = result.status === 'authentic' && result.expired ? 'untrusted' : result.status;
+
+  const verdicts = {
+    authentic: result.expired
+      ? '⚠ Authentic, but this voucher has expired'
+      : '✓ Authentic: signed by a trusted Daily Grind key and unchanged',
+    untrusted: '⚠ Signature valid, but the signer isn\'t trusted. Contents are intact; the issuer is unproven.',
+    invalid: '✗ Invalid: do not accept this document',
+  };
+  const children = [el('p', { class: 'dg-verdict', text: verdicts[result.status] })];
+
+  const checklist = el('ul', { class: 'dg-checks' });
+  for (const c of result.checks) {
+    const icon = c.ok === true ? '✓' : c.ok === false ? '✗' : '?';
+    checklist.append(el('li', { 'data-ok': String(c.ok) },
+      el('span', { class: 'dg-check-icon', text: icon, 'aria-hidden': 'true' }),
+      el('span', { text: c.label + (c.detail ? ` (${c.detail})` : '') }),
+    ));
+  }
+  children.push(checklist);
+
+  if (result.envelope) {
+    children.push(renderDocumentPreview(result.envelope));
+    if (result.status === 'untrusted') {
+      const signer = result.envelope.signer;
+      children.push(el('div', { class: 'dg-trust-prompt' },
+        el('p', { text: `Only trust this key if you've confirmed its fingerprint ${formatFingerprint(signer.keyId)} with The Daily Grind through a separate channel. Anyone can create a key and call it "${signer.label}".` }),
+        el('button', {
+          type: 'button', class: 'btn dg-btn-secondary', text: 'I verified the fingerprint, so trust this signer', onclick: async () => {
+            const ok = await addTrustedKey(JSON.stringify({ format: 'daily-grind-public-key/v1', ...signer }));
+            if (ok) verify();
+          },
+        }),
+      ));
+    }
+  }
+  out.replaceChildren(...children);
+}
+
+function renderDocumentPreview(env) {
+  const d = env.document;
+  const rows = [];
+  const row = (k, v) => rows.push(el('tr', {}, el('th', { scope: 'row', text: k }), el('td', { text: v })));
+  if (d.type === 'receipt') {
+    row('Receipt', d.receiptId);
+    row('Store', d.store);
+    row('Customer', d.customer);
+    row('Issued', new Date(d.issuedAt).toLocaleString());
+    for (const it of d.items) row(`${it.quantity} × ${it.name}`, money(it.unitPriceCents * it.quantity));
+    row('Subtotal', money(d.subtotalCents));
+    row('Tax', money(d.taxCents));
+    row('Total', money(d.totalCents));
+  } else {
+    row('Voucher code', d.voucherCode);
+    row('Value', money(d.amountCents));
+    row('For', d.recipient);
+    row('From', d.from);
+    row('Expires', d.expiresOn);
+    if (d.message) row('Message', d.message);
+    row('Issued', new Date(d.issuedAt).toLocaleString());
+  }
+  row('Signed by', `${env.signer.label} (${formatFingerprint(env.signer.keyId)})`);
+  row('Algorithm', SUITES[env.signer.suite].label);
+  row('Signed at', new Date(env.signedAt).toLocaleString());
+  return el('div', { class: `dg-preview dg-preview-${d.type}` },
+    el('h4', { text: d.type === 'receipt' ? 'Order receipt' : 'Gift voucher' }),
+    el('table', {}, el('tbody', {}, ...rows)),
+  );
+}
+
+/* ------------------------------------------------------------------ */
+/* Boot                                                                */
+/* ------------------------------------------------------------------ */
+
+async function init() {
+  const root = $('receipts-vouchers');
+  if (!root) return;
+  if (!window.isSecureContext || !crypto?.subtle) {
+    setStatus($('dg-key-status'), 'Signing needs a secure (HTTPS) connection. Signing and verification are disabled.', 'error');
+    root.querySelectorAll('button, input, textarea, select').forEach((n) => { n.disabled = true; });
+    return;
+  }
+
+  initIssueForms();
+  initVerify();
+  $('dg-generate').addEventListener('click', generateKey);
+  $('dg-trust-form').addEventListener('submit', async (e) => {
+    e.preventDefault();
+    if (await addTrustedKey($('dg-trust-input').value.trim())) $('dg-trust-input').value = '';
+  });
+
+  state.trusted = loadTrusted();
+  renderTrusted();
+  try {
+    state.keys = (await keyDb.all()).sort((a, b) => a.createdAt.localeCompare(b.createdAt));
+  } catch (e) {
+    setStatus($('dg-key-status'), `Key storage unavailable (${e.message}). Keys won't persist.`, 'error');
+  }
+  renderKeys();
+  await initSuiteSelect();
+}
+
+init();
