+  // ------------------------------------------------------------- sizing
+  let cssW = 0, cssH = 0;
+  let layoutDX = 0, layoutDY = 0; // form's untransformed layout offset within the canvas
+  const measureLayout = () => {
+    const prev = form.style.transform;
+    form.style.transform = 'none';
+    const fr = form.getBoundingClientRect();
+    const cr = canvas.getBoundingClientRect();
+    layoutDX = fr.left - cr.left;
+    layoutDY = fr.top - cr.top;
+    form.style.transform = prev;
+  };
