+  // ---------------------------------------------------------- interaction
+  // While the user is engaging with the label, ease the box round to face them.
+  let hovering = false;
+  let focused = false;
+  form.addEventListener('pointerenter', () => { hovering = true; });
+  form.addEventListener('pointerleave', () => { hovering = false; });
+  form.addEventListener('focusin', () => { focused = true; });
+  form.addEventListener('focusout', () => {
+    // Defer so focus moving between controls inside the form doesn't flicker.
+    setTimeout(() => { focused = form.contains(document.activeElement); }, 0);
+  });
