+  // ------------------------------------------------------------- render loop
+  const TWO_PI = Math.PI * 2;
+  let angle = -0.6;
+  let speed = 0.55; // rad/s
+  let last = performance.now();
+  let visible = true;
+  new IntersectionObserver(([e]) => { visible = e.isIntersecting; }).observe(stage);
+
+  // Element px (x, y) on the form -> model-space point on the front face.
+  const faceMap = new Float32Array([
+    W / FORM_W, 0, 0, 0,
+    0, -H / FORM_H, 0, 0,
+    0, 0, 1, 0,
+    -W / 2, H / 2, D / 2, 1,
+  ]);
+
+  const frame = (now) => {
+    requestAnimationFrame(frame);
+    const dt = Math.min(0.05, (now - last) / 1000);
+    last = now;
+    if (!visible || !cssW || !cssH) return;
+
+    const engaged = hovering || focused;
+    const targetSpeed = engaged || reduceMotion.matches ? 0 : 0.55;
+    speed += (targetSpeed - speed) * Math.min(1, dt * 4);
+    angle += speed * dt;
+    if (engaged || reduceMotion.matches) {
+      // Turn toward the nearest front-facing orientation.
+      const nearest = Math.round(angle / TWO_PI) * TWO_PI;
+      angle += (nearest - angle) * Math.min(1, dt * 5);
+    }
+    angle %= TWO_PI * 1000;
+    const tilt = engaged || reduceMotion.matches ? 0.04 : 0.12 + Math.sin(now / 1400) * 0.05;
+
+    const aspect = cssW / cssH;
+    const dist = aspect < 0.9 ? 4.8 / aspect : 4.6;
+    const proj = perspective(Math.PI / 5, aspect, 0.1, 50);
+    const model = mul(rotX(tilt), rotY(angle));
+    const view = translate(0, 0, -dist);
+    const mvp = mul(proj, mul(view, model));
+
+    gl.clearColor(0, 0, 0, 0);
+    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
+    gl.enable(gl.DEPTH_TEST);
+    gl.enable(gl.CULL_FACE);
+    gl.useProgram(prog);
+    gl.uniformMatrix4fv(loc.mvp, false, mvp);
+    gl.uniformMatrix4fv(loc.model, false, model);
+    gl.uniform1i(loc.tex, 0);
+    gl.activeTexture(gl.TEXTURE0);
+    order.forEach((name, i) => {
+      gl.bindTexture(gl.TEXTURE_2D, textures[name]);
+      // Keep the live form crisp and readable: only light it lightly.
+      gl.uniform1f(loc.lit, name === 'front' ? 0.35 : 1.0);
+      gl.drawArrays(gl.TRIANGLES, i * 6, 6);
+    });
+
+    // --- Sync the real DOM form with the drawn front face -------------------
+    // Is the front face pointing at the camera (and not too oblique)?
+    const centerW = xform(model, [0, 0, D / 2, 1]);
+    const normalW = xform(model, [0, 0, 1, 0]);
+    const toCam = [-centerW[0], -centerW[1], dist - centerW[2]];
+    const len = Math.hypot(...toCam);
+    const facing = (normalW[0] * toCam[0] + normalW[1] * toCam[1] + normalW[2] * toCam[2]) / len;
+    const hidden = facing < 0.2;
+    if (form.dataset.hidden !== String(hidden)) form.dataset.hidden = String(hidden);
+
+    // clip space -> canvas CSS pixels
+    const viewport = new Float32Array([
+      cssW / 2, 0, 0, 0,
+      0, -cssH / 2, 0, 0,
+      0, 0, 1, 0,
+      cssW / 2, cssH / 2, 0, 1,
+    ]);
+    // Undo the form's own layout offset so the transform is relative to the canvas origin.
+    const m = mul(translate(-layoutDX, -layoutDY, 0), mul(viewport, mul(mvp, faceMap)));
+    form.style.transform = `matrix3d(${Array.from(m).join(',')})`;
+  };
+  requestAnimationFrame(frame);
+})();

