+import { useCallback, useEffect, useId, useRef, useState } from 'react';
+
+/**
+ * Developer diagnostics connection widget.
+ *
+ * Connects from this (public, https) page to:
+ *  - a hardware test device on the reader's private LAN (RFC 1918 / .local) → `local-network` permission
+ *  - a companion CLI on the reader's own machine (127.0.0.1 / localhost / [::1]) → `loopback-network` permission
