+  const started = performance.now();
+  const init: RequestInit & { targetAddressSpace: AddressSpace } = {
+    method: 'GET',
+    mode: 'cors',
+    credentials: 'omit',
+    cache: 'no-store',
+    referrerPolicy: 'no-referrer',
+    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
+    // Declares the target address space before DNS resolution: exempts http:// from
+    // mixed-content blocking once permission is granted, and makes the browser abort
+    // if the host unexpectedly resolves outside this address space.
+    targetAddressSpace: space,
+  };
