+    let body = await res.text();
+    const type = res.headers.get('content-type') ?? '';
+    if (type.includes('json')) {
+      try {
+        body = JSON.stringify(JSON.parse(body), null, 2);
+      } catch {
+        /* show raw text */
+      }
