+  checking: { label: 'Checking…', cls: 'bg-gray-100 text-gray-700' },
+  granted: { label: 'Access allowed', cls: 'bg-green-100 text-green-800' },
+  prompt: { label: 'Will ask on connect', cls: 'bg-amber-100 text-amber-900' },
+  denied: { label: 'Access blocked', cls: 'bg-red-100 text-red-800' },
+  unsupported: { label: 'No permission API', cls: 'bg-gray-100 text-gray-700' },
+};
+
+function loadSaved(key: string): { host: string; port: string; path: string } | null {
+  try {
