+        onSubmit={(e) => {
+          e.preventDefault();
+          void connect();
+        }}
+      >
+        <div className="col-span-2 sm:col-span-1">
+          <label htmlFor={`${id}-host`} className="block text-xs font-medium text-gray-700 mb-1">
+            {cfg.hostLabel}
+          </label>
+          <input
+            id={`${id}-host`}
+            value={host}
+            onChange={(e) => setHost(e.target.value)}
+            required
+            autoComplete="off"
+            spellCheck={false}
+            inputMode="url"
+            className="w-full px-3 py-2 border border-gray-300 font-mono text-sm focus:outline-none focus:ring-2 focus:ring-amber-400"
+          />
+        </div>
+        <div className="col-span-2 sm:col-span-1">
+          <label htmlFor={`${id}-port`} className="block text-xs font-medium text-gray-700 mb-1">
+            Port
+          </label>
+          <input
+            id={`${id}-port`}
+            value={port}
+            onChange={(e) => setPort(e.target.value)}
+            required
+            inputMode="numeric"
+            pattern="[0-9]{1,5}"
+            autoComplete="off"
+            className="w-full px-3 py-2 border border-gray-300 font-mono text-sm focus:outline-none focus:ring-2 focus:ring-amber-400"
+          />
+        </div>
+        <div className="col-span-2">
+          <label htmlFor={`${id}-path`} className="block text-xs font-medium text-gray-700 mb-1">
+            Status endpoint
+          </label>
+          <input
+            id={`${id}-path`}
+            value={path}
+            onChange={(e) => setPath(e.target.value)}
+            required
+            autoComplete="off"
+            spellCheck={false}
+            className="w-full px-3 py-2 border border-gray-300 font-mono text-sm focus:outline-none focus:ring-2 focus:ring-amber-400"
+          />
+        </div>
+        <div className="col-span-2">
+          <button
+            type="submit"
+            disabled={busy || !secure}
+            className="w-full bg-gray-900 text-white font-semibold py-2 px-4 hover:bg-amber-400 hover:text-gray-900 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
+          >
+            {busy ? 'Connecting…' : status.kind === 'connected' ? 'Reconnect' : 'Connect'}
+          </button>
+          {permission === 'prompt' && secure && (
+            <p className="mt-2 text-xs text-gray-600">
+              Your browser will ask for permission to access your {permissionLabel.toLowerCase()} when you
+              click Connect. The request goes straight from your browser to the address above. Nothing is
+              sent to our servers.
+            </p>
+          )}
+        </div>
+      </form>
+
+      {permission === 'denied' && (
+        <div className="mb-4 p-3 text-sm bg-red-50 border border-red-200 text-red-900" role="note">
+          <p className="font-semibold mb-1">{permissionLabel} access is blocked for this site.</p>
+          <p>
+            To turn it back on, click the site controls icon next to the address bar, open{' '}
+            <strong>Site settings</strong>, and set <strong>{permissionLabel}</strong> to <em>Allow</em> or{' '}
+            <em>Ask</em>. Then reload the page.
+          </p>
+        </div>
+      )}
+
+      <div aria-live="polite" className="mt-auto">
+        {status.kind === 'connected' && (
+          <div className="p-3 text-sm bg-green-50 border border-green-200">
+            <p className="font-semibold text-green-900">
+              Connected · HTTP {status.httpStatus} · {status.latencyMs} ms
+            </p>
+            <p className="text-xs text-green-800 mb-2">
+              Last checked {status.at.toLocaleTimeString()}
+            </p>
+            {status.body && (
+              <pre className="max-h-64 overflow-auto bg-white border border-green-100 p-2 text-xs font-mono whitespace-pre-wrap break-all">
+                {status.body}
+              </pre>
+            )}
+          </div>
+        )}
+        {status.kind === 'error' && (
+          <div className="p-3 text-sm bg-red-50 border border-red-200 text-red-900" role="alert">
+            <p className="font-semibold">{status.message}</p>
+            {status.hint && <p className="mt-1 whitespace-pre-wrap break-words">{status.hint}</p>}
+          </div>
+        )}
+      </div>
+    </section>
+  );
+}
+
+export default function DiagnosticsConnect() {
+  // Assume secure during SSR; correct on hydration.
+  const [secure, setSecure] = useState(true);
+  useEffect(() => setSecure(window.isSecureContext), []);
+
+  return (
+    <div>
+      {!secure && (
+        <div className="mb-6 p-4 bg-amber-50 border border-amber-300 text-amber-950 text-sm" role="alert">
+          This page isn't running in a secure context (https). Browsers automatically deny local and loopback
+          network access to insecure pages. Open the https version of this page to use the diagnostics tools.
+        </div>
+      )}
+      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
+        {TARGETS.map((cfg) => (
+          <TargetCard key={cfg.space} cfg={cfg} secure={secure} />
+        ))}
+      </div>
+    </div>
+  );
+}
