+  padding: 10px 20px;
+  text-decoration: none;
+  border-radius: 5px;
+  margin-top: 15px;
+  transition: background 0.3s;
+}
+
+.btn:hover {
+  background: #3e2723;
+}
+
+footer {
+  background: var(--secondary);
+  text-align: center;
+  padding: 40px 20px;
+  margin-top: 40px;
+}
+
+.footer-links {
+  margin-bottom: 20px;
+}
+
+.footer-links a {
+  margin: 0 10px;
+  color: var(--text);
+  text-decoration: none;
+  font-size: 0.85rem;
+}
+
+.section-title {
+  text-align: center;
+}
+
+.link-button {
+  background: none;
+  border: 0;
+  color: var(--text);
+  font: inherit;
+  font-size: 0.85rem;
+  cursor: pointer;
+  margin: 0 10px;
+  padding: 0;
+}
+
+.link-button:hover,
+.footer-links a:hover {
+  text-decoration: underline;
+}
+
+/* Privacy choices dialog */
+.privacy-dialog {
+  max-width: 32rem;
+  margin: auto;
+  padding: 24px;
+  border: 0;
+  border-radius: 8px;
+  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
+  color: var(--text);
+}
+
+.privacy-dialog::backdrop {
+  background: rgba(0, 0, 0, 0.5);
+}
+
+.privacy-dialog h2 {
+  color: var(--primary);
+  margin-bottom: 10px;
+}
+
+.privacy-dialog p,
+.privacy-dialog fieldset {
+  margin-bottom: 15px;
+}
+
+.privacy-dialog fieldset {
+  border: 1px solid var(--secondary);
+  border-radius: 6px;
+  padding: 10px 15px;
+}
+
+.privacy-dialog label {
+  display: block;
+  margin: 6px 0;
+}
+
+.privacy-dialog small {
+  display: block;
+  color: #6d4c41;
+  margin-left: 1.5rem;
+}
+
+.privacy-dialog .gpc-notice {
+  background: #e8f5e9;
+  border-radius: 4px;
+  padding: 8px 12px;
+}
+
+.privacy-dialog .status {
+  min-height: 1.6em;
+  font-size: 0.9rem;
+}
+
+.dialog-actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+  justify-content: flex-end;
+}
+
+.dialog-actions button {
+  font: inherit;
+  cursor: pointer;
+  border-radius: 5px;
+  padding: 8px 16px;
+  border: 1px solid var(--primary);
+  background: white;
+  color: var(--primary);
+}
+
+.dialog-actions button.primary {
+  background: var(--primary);
+  color: white;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  * {
+    transition: none !important;
+  }
+}
