+/**
+ * Button look, reusable for both shadow elements (`.btn`) and slotted
+ * light-DOM links (`::slotted(a)`), which can't be targeted by a class rule.
+ */
+export function buttonRules(selector, hoverSelector) {
+  return `
+    ${selector} {
+      display: inline-block;
+      background: var(--_primary);
+      color: #fff;
+      padding: 10px 20px;
+      border: 0;
+      border-radius: 5px;
+      font: inherit;
+      text-decoration: none;
+      cursor: pointer;
+      transition: background-color 0.3s;
+    }
+    ${hoverSelector} { background: var(--_primary-dark); }
+  `;
+}
+
+/**
+ * Styles shared by every Daily Grind component.
+ * One CSSStyleSheet instance is created and adopted by each shadow root, so
+ * the rules are parsed once and never leak into (or out of) the page.
+ *
+ * Theme tokens are CSS custom properties, which inherit through shadow
+ * boundaries — override them on :root (or any ancestor) to re-theme.
+ */
+export const sharedStyles = new CSSStyleSheet();
+
+sharedStyles.replaceSync(`
+  :host {
+    --_primary: var(--dg-primary, #4e342e);
+    --_primary-dark: var(--dg-primary-dark, #3e2723);
+    --_secondary: var(--dg-secondary, #d7ccc8);
+    --_accent: var(--dg-accent, #ffab40);
+    --_text: var(--dg-text, #3e2723);
+    --_surface: var(--dg-surface, #ffffff);
+    --_radius: var(--dg-radius, 8px);
+    --_focus-ring: 3px solid var(--_accent);
+    box-sizing: border-box;
+  }
+
+  *, *::before, *::after { box-sizing: inherit; }
+
+  [hidden] { display: none !important; }
+
+  .visually-hidden {
+    position: absolute !important;
+    width: 1px;
+    height: 1px;
+    padding: 0;
+    margin: -1px;
+    overflow: hidden;
+    clip: rect(0 0 0 0);
+    white-space: nowrap;
+    border: 0;
+  }
+
+  ${buttonRules('.btn', '.btn:hover')}
+
+  :focus-visible {
+    outline: var(--_focus-ring);
+    outline-offset: 2px;
+  }
+
+  @media (prefers-reduced-motion: reduce) {
+    *, *::before, *::after {
+      transition-duration: 0.01ms !important;
+      animation-duration: 0.01ms !important;
+    }
+  }
+`);
+
+/** Builds a component-specific stylesheet. */
+export function css(text) {
+  const sheet = new CSSStyleSheet();
+  sheet.replaceSync(text);
+  return sheet;
+}
+
